   452|function deriveBlocker(agentId: ExecutiveAgentId): string {
   453|  const def = EXECUTIVE_AGENTS[agentId];
   454|  const entDef = ENTERPRISE_AGENTS[agentId as keyof typeof ENTERPRISE_AGENTS];
   455|  const fwAgent = entDef?.frameworkAgent ?? 'operations';
   456|  const fwDef = AGENTS[fwAgent as keyof typeof AGENTS];
   457|  if (!fwDef) return 'No framework agent binding';
   458|  if (fwDef.approvalLevel <= 2) return 'Approval level 2 — can only recommend, not execute';
   459|  if (fwDef.approvalLevel === 3) return 'Approval level 3 — can draft patches but not deploy without owner approval';
   460|  return 'No current blocker identified';
   461|}
