   463|// ── Audit Execution ──────────────────────────────────────────────────────────
   464|
   465|export function runAgentAudit(): AgentAuditResult[] {
   466|  const results: AgentAuditResult[] = [];
   467|  let agentNumber = 0;
   468|
   469|  for (const agentId of EXECUTIVE_AGENT_IDS) {
   470|    agentNumber++;
   471|    const def = EXECUTIVE_AGENTS[agentId];
   472|    const entDef = ENTERPRISE_AGENTS[agentId as keyof typeof ENTERPRISE_AGENTS];
   473|    const frameworkAgentId = entDef?.frameworkAgent ?? 'operations';
   474|    const fwDef = AGENTS[frameworkAgentId as keyof typeof AGENTS];
   475|    const roleAssignment = ROLE_ASSIGNMENTS[agentId];
   476|
   477|    const capabilities = assessAgent(agentId);
   478|    const scorePercentage = computeScorePercentage(capabilities);
   479|    const seniority = classifySeniority(scorePercentage);
   480|
   481|    results.push({
   482|      agentNumber,
   483|      executiveAgentId: agentId,
   484|      currentName: def.name,
   485|      currentRole: def.role,
   486|      currentEngine: def.engine,
   487|      frameworkAgentId,
   488|      allowedTools: fwDef?.allowedTools ?? [],
   489|      riskLevel: entDef?.riskLevel ?? 'low',
   490|      canExecuteCode: fwDef?.allowedTools.includes('code_patch_proposal') ?? false,
   491|      capabilities,
   492|      scorePercentage,
   493|      seniority,
   494|      assignedRole: roleAssignment.role,
   495|      assignedRoleTitle: roleAssignment.title,
   496|      mainGap: deriveMainGap(agentId, capabilities),
   497|      filesOwned: roleAssignment.filesOwned,
   498|      currentBlocker: deriveBlocker(agentId),
   499|    });
   500|  }
   501|
   502|  return results;
   503|}
