  if (effectiveScore >= 85 && hasRuntimeEvidence) return 'SENIOR';
  if (effectiveScore >= 65) return 'MID';
  if (effectiveScore >= 40) return 'JUNIOR';
  return 'NOT_A_DEVELOPER';
}"}]}

